kubectl --context kind-amc-p206 -n default exec deploy/amc-rd-amc -c amc-studio -- sh -c cd /data/amc && amc ops verify >/dev/null && amc ops print | node -e '
const fs = require("fs");
const Database = require("/opt/amc/node_modules/better-sqlite3");
const policy = JSON.parse(fs.readFileSync(0, "utf8"));
const dek = JSON.parse(fs.readFileSync(".amc/keys/ledger-dek.json", "utf8"));
const db = new Database(".amc/evidence.sqlite", { readonly: true, fileMustExist: true });
const inline = db.prepare("SELECT payload_inline AS p FROM evidence_events WHERE payload_inline IS NOT NULL").all();
const encryptedRows = inline.filter((row) => row.p.startsWith("amcenc:v1:")).length;
process.stdout.write(JSON.stringify({ ledgerEncryptionEnabled: policy.opsPolicy.encryption.ledgerEncryptionEnabled === true,
  wrapProvider: dek.keys.find((key) => key.keyVersion === dek.activeVersion)?.providerId ?? null,
  encryptedRows, plaintextRows: inline.length - encryptedRows }));'

kubectl --context kind-amc-p206 -n default exec deploy/amc-rd-amc -c amc-studio -- node -e 
const Database = require("/opt/amc/node_modules/better-sqlite3");
const db = new Database(process.argv[1], { readonly: true, fileMustExist: true });
const rows = db.prepare("SELECT event_hash, prev_event_hash, session_id FROM evidence_events ORDER BY rowid").all();
let linked = true;
for (let i = 1; i < rows.length; i += 1) if (rows[i].prev_event_hash !== rows[i - 1].event_hash) linked = false;
const migrations = db.prepare("SELECT version FROM schema_migrations ORDER BY version").all().map((row) => row.version);
const integrity = db.prepare("PRAGMA integrity_check").all().map((row) => Object.values(row)[0]).join(";");
process.stdout.write(JSON.stringify({ count: rows.length, head: rows.at(-1)?.event_hash ?? null, hashes: rows.map((row) => row.event_hash), sessions: rows.map((row) => row.session_id), linked, migrations, integrity }));
